#!/usr/bin/env python3
"""Create an offline interactive report from retained experiment artifacts."""
import argparse
import hashlib
import json
from pathlib import Path
from analyze import summarize_faults


def load_subject(matrix_path):
    matrix=json.loads(matrix_path.read_text())
    path=matrix_path.parent/'analysis.json'
    expected=hashlib.sha256(json.dumps(matrix,sort_keys=True,allow_nan=False).encode()).hexdigest()
    if path.exists():
        analysis=json.loads(path.read_text())
        if analysis.get('baselineMatrixDigest')!=expected:
            raise ValueError(f'Retained analysis does not match matrix: {matrix_path}')
    else:
        analysis={'complete':False,'baselineComplete':False,'tests':[],'requirements':[],
            'redundancyGroups':[], 'summary':{'tests':len(matrix.get('tests',[])),'acceptedMutants':0,'killedMutants':0,
            'subsumingRequirements':0,'greedyCoreTests':0,'unexplainedSurvivors':0,'excludedMutants':len(matrix.get('mutants',[]))}}
    return matrix,analysis


def collect(root, secondary_root=None):
    subjects=[]
    candidates=[root/'matrix.json',*root.glob('current/*/matrix.json'),root/'native/matrix.json']
    for matrix_path in sorted(path for path in candidates if path.exists()):
        path=matrix_path.parent/'analysis.json'
        if 'dependencies' in str(path) or any(part in {'history','history-continuation'} for part in path.parts):
            continue
        matrix,analysis=load_subject(matrix_path)
        subjects.append({'id':path.parent.name,'analysis':analysis,'matrix':matrix,
                         'evidence':str(path.parent.resolve())})
    attempts=[];evaluations=[]
    for history in [root/'history',root/'history-continuation']:
        records=json.loads((history/'attempts.json').read_text()) if (history/'attempts.json').exists() else []
        for fault in records:
            directory=history/fault['id']
            fault['evidence']=str(directory.resolve())
            for name,expected in fault.get('recordDigests',{}).items():
                if hashlib.sha256((directory/name).read_bytes()).hexdigest()!=expected:
                    raise ValueError('Retained historical evidence changed: '+str(directory/name))
            analysis=None
            if (directory/'analysis.json').exists():
                analysis=load_subject(directory/'matrix.json')[1]
                fault['analysisSummary']=analysis['summary']
            if fault.get('verified') and (directory/'evaluation.json').exists():
                evaluation=json.loads((directory/'evaluation.json').read_text())
                provenance=evaluation.get('selectionProvenance',{})
                if analysis is None or not analysis['complete'] or any(provenance.get(key)!=analysis[key] for key in ['baselineMatrixDigest','baselineTestInventoryDigest']):
                    raise ValueError('Historical evaluation does not match a complete matrix: '+str(directory))
                if any(evaluation['fault'].get(key)!=fault.get(key) for key in ['id','fix','parent','verified','relatedGroup','killedBy']):
                    raise ValueError('Historical evaluation describes a different fault: '+str(directory))
                evaluations.append(evaluation)
            attempts.append(fault)
    if len({fault['id'] for fault in attempts})!=len(attempts):
        raise ValueError('Historical candidates duplicated between experiment registrations')
    aggregate=summarize_faults(evaluations)
    secondary=[]
    if secondary_root is not None:
        by_id={s['id']:s for s in subjects}
        for path in sorted(secondary_root.glob('*/matrix.json')):
            matrix,analysis=load_subject(path)
            original=by_id.get(path.parent.name)
            if original is None or matrix['provenance'].get('primaryMatrixSha256')!=hashlib.sha256(Path(original['evidence'],'matrix.json').read_bytes()).hexdigest():
                raise ValueError('Secondary matrix does not match retained primary: '+str(path))
            if matrix['provenance'].get('sensitivityPolicy')!='posthoc-test-failures-v1':
                raise ValueError('Secondary matrix has an unsupported sensitivity policy')
            categories={'assertionOnly':0,'otherOnly':0,'mixed':0}
            excluded={column['id'] for column in analysis['excluded']}
            for mutant in matrix['mutants']:
                if mutant['status']=='killed' and mutant['id'] not in excluded:
                    c=mutant.get('failureCategories',{})
                    if any(not isinstance(c.get(key),list) or any(not isinstance(test,str) for test in c[key]) or len(set(c[key]))!=len(c[key]) for key in ['assertionTests','otherFailureTests']):
                        raise ValueError('Secondary kill lacks valid failure categories')
                    killers={test for test,outcome in mutant['outcomes'].items() if outcome=='killed'}
                    if set(c['assertionTests'])|set(c['otherFailureTests'])!=killers:
                        raise ValueError('Secondary failure categories disagree with observed kills')
                    assertions=bool(c['assertionTests']);others=bool(c['otherFailureTests'])
                    categories['mixed' if assertions and others else 'assertionOnly' if assertions else 'otherOnly']+=1
            secondary.append({'id':original['id']+' [posthoc]','primaryId':original['id'],'analysis':analysis,'matrix':matrix,
                              'evidence':str(path.parent.resolve()),'failureCategories':categories})
    metadata_path=root/'report-metadata.json'
    metadata=json.loads(metadata_path.read_text()) if metadata_path.exists() else {}
    if not isinstance(metadata,dict):
        raise ValueError('report metadata must be an object')
    return {**metadata,'subjects':subjects,'history':attempts,'aggregate':aggregate,'secondarySubjects':secondary}


def render(data):
    payload=json.dumps(data,separators=(',',':'),allow_nan=False).replace('<','\\u003c')
    return TEMPLATE.replace('__DATA__',payload)


def main():
    p=argparse.ArgumentParser(description=__doc__);p.add_argument('--root',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--secondary-root',type=Path)
    args=p.parse_args();args.output.parent.mkdir(parents=True,exist_ok=True);args.output.write_text(render(collect(args.root,args.secondary_root)))

